    private static List<Municipio> LISTA;
    private static List<double[][]> CONTORNOS;
    private static List<String> NOMBRES_CONTORNO;
    private static List<String> DEPARTAMENTOS;

    private static synchronized void cargar() {
        if (LISTA != null) return;

        List<Municipio> ms = new ArrayList<>(1200);
        String datos = M0 +
            M1;
        for (String linea : datos.split("\n")) {
            if (linea.isEmpty()) continue;
            String[] p = linea.split("\\|");
            if (p.length < 5) continue;
            ms.add(new Municipio(p[0], p[1], p[2],
                    Double.parseDouble(p[3]), Double.parseDouble(p[4])));
        }
        LISTA = Collections.unmodifiableList(ms);

        LinkedHashSet<String> ds = new LinkedHashSet<>();
        for (Municipio m : ms) ds.add(m.departamento);
        List<String> dl = new ArrayList<>(ds);
        Collections.sort(dl);
        DEPARTAMENTOS = Collections.unmodifiableList(dl);

        List<double[][]> cs = new ArrayList<>();
        List<String> ns = new ArrayList<>();
        String geo = P0 +
            P1;
        for (String linea : geo.split("\n")) {
            if (linea.isEmpty()) continue;
            int barra = linea.indexOf('|');
            if (barra < 0) continue;
            String[] pares = linea.substring(barra + 1).split(" ");
            double[][] pts = new double[pares.length][2];
            for (int i = 0; i < pares.length; i++) {
                int coma = pares[i].indexOf(',');
                pts[i][0] = Double.parseDouble(pares[i].substring(0, coma));
                pts[i][1] = Double.parseDouble(pares[i].substring(coma + 1));
            }
            cs.add(pts);
            ns.add(linea.substring(0, barra));
        }
        CONTORNOS = Collections.unmodifiableList(cs);
        NOMBRES_CONTORNO = Collections.unmodifiableList(ns);
    }

    public static List<Municipio> todos() { cargar(); return LISTA; }

    public static List<String> departamentos() { cargar(); return DEPARTAMENTOS; }

    public static List<double[][]> contornos() { cargar(); return CONTORNOS; }

    public static List<String> nombresContorno() { cargar(); return NOMBRES_CONTORNO; }

    public static List<Municipio> buscar(String texto, String depto) {
        cargar();
        String t = normalizar(texto);
        List<Municipio> out = new ArrayList<>();
        for (Municipio m : LISTA) {
            if (depto != null && !depto.isEmpty() && !depto.equals(m.departamento)) continue;
            if (t.isEmpty()
                    || m.nombreNorm.contains(t)
                    || m.deptoNorm.contains(t)
                    || m.codigoDane.startsWith(t)) {
                out.add(m);
            }
        }
        return out;
    }

    public static Municipio porCodigo(String codigoDane) {
        cargar();
        for (Municipio m : LISTA) if (m.codigoDane.equals(codigoDane)) return m;
        return null;
    }

    public static Municipio masCercano(double lat, double lon) {
        cargar();
        Municipio mejor = null;
        double d2 = Double.MAX_VALUE;
        for (Municipio m : LISTA) {
            double dx = (m.lon - lon) * Math.cos(Math.toRadians(lat));
            double dy = (m.lat - lat);
            double d = dx*dx + dy*dy;
            if (d < d2) { d2 = d; mejor = m; }
        }
        return mejor;
    }

    private static final Pattern DIACRITICOS =
            Pattern.compile("\\p{InCombiningDiacriticalMarks}+");

    public static String normalizar(String s) {
        if (s == null) return "";
        String n = Normalizer.normalize(s.trim().toLowerCase(), Normalizer.Form.NFD);
        return DIACRITICOS.matcher(n).replaceAll("");
    }

    private static Municipio ACTUAL;

    public static Municipio actual() { return ACTUAL; }

    public static void setActual(Municipio m) { ACTUAL = m; }

    public static String descripcionActual() {
        return ACTUAL == null ? "sin definir"
                : ACTUAL.nombreCompleto() + " (" + ACTUAL.codigoDane + ")";
    }
